// Vérifie la signature envoyée par site/api/lib/Webhook.php :
// X-AC-Signature = "sha256=" + HMAC-SHA256(AC_HMAC_SECRET, X-AC-Timestamp + "." + corps brut), horodatage ± 5 min.
const crypto = require('crypto');
const secret = $env.AC_HMAC_SECRET || '';
if (secret.length < 32) throw new Error('AC_HMAC_SECRET absent ou trop court');
const item = $input.first();
const h = item.json.headers || {};
const ts = String(h['x-ac-timestamp'] || '');
const sig = String(h['x-ac-signature'] || '');
let brut = '';
try {
  brut = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} catch (e) {
  const bin = item.binary && item.binary.data;
  brut = bin && bin.data && !String(bin.data).startsWith('filesystem')
    ? Buffer.from(bin.data, 'base64').toString('utf8')
    : JSON.stringify(item.json.body); // repli : identique à json_encode (barres et Unicode non échappés)
}
const attendue = 'sha256=' + crypto.createHmac('sha256', secret).update(ts + '.' + brut).digest('hex');
const frais = /^\d{10}$/.test(ts) && Math.abs(Date.now() / 1000 - Number(ts)) <= 300;
const valide = frais && sig.length === attendue.length && crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(attendue));
let demande = null;
if (valide) { try { demande = JSON.parse(brut); } catch (e) { demande = item.json.body; } }
return [{ json: { valide, raison: valide ? '' : (frais ? 'signature' : 'horodatage'), demande } }];

// Jetons signés partagés avec site/api (lib/Jeton.php) : base64url(JSON).base64url(HMAC-SHA256).
// Prérequis : NODE_FUNCTION_ALLOW_BUILTIN=crypto dans l'environnement de n8n.
const crypto = require('crypto');
const b64 = (buf) => Buffer.from(buf).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
function creerJeton(donnees, validiteS) {
  const secret = $env.AC_ACTION_SECRET;
  if (!secret || secret.length < 32) throw new Error('AC_ACTION_SECRET absent ou trop court');
  const d = { ...donnees, x: Math.floor(Date.now() / 1000) + validiteS, n: crypto.randomBytes(4).toString('hex') };
  const charge = b64(JSON.stringify(d));
  return charge + '.' + b64(crypto.createHmac('sha256', secret).update(charge).digest());
}
function verifierJeton(jeton) {
  const secret = $env.AC_ACTION_SECRET || '';
  const [charge, sig] = String(jeton || '').split('.');
  if (!charge || !sig || secret.length < 32) return null;
  const attendue = b64(crypto.createHmac('sha256', secret).update(charge).digest());
  if (attendue.length !== sig.length || !crypto.timingSafeEqual(Buffer.from(attendue), Buffer.from(sig))) return null;
  let d;
  try { d = JSON.parse(Buffer.from(charge.replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf8')); } catch (e) { return null; }
  if (!d || !d.x || d.x < Date.now() / 1000) return null;
  return d;
}
const lienAction = (donnees, jours) => ($env.AC_N8N_URL || '') + '/webhook/ac-action?t=' + creerJeton(donnees, jours * 86400);
const lienStop = (email) => ($env.AC_N8N_URL || '') + '/webhook/ac-stop?t=' + creerJeton({ a: 'stop', e: email }, 400 * 86400);

// Alphabet GSM 03.38 : remplace ce qui ferait passer le SMS à 70 caractères.
function versGsm(t) {
  const r = { 'ê': 'e', 'ë': 'e', 'â': 'a', 'î': 'i', 'ï': 'i', 'ô': 'o', 'û': 'u', 'ç': 'c', 'À': 'A', 'Â': 'A', 'È': 'E', 'Ê': 'E', 'Î': 'I',
    'Ô': 'O', 'Û': 'U', 'œ': 'oe', 'Œ': 'OE', '«': '"', '»': '"', '’': "'", '‘': "'", '“': '"', '”': '"', '–': '-', '—': '-', '…': '...', ' ': ' ', ' ': ' ' };
  return String(t).replace(/[^\n -~£¥èéùìòÇØøÅåÆæßÉÄÖÑÜ§¿äöñüà¡]/g, (c) => (r[c] !== undefined ? r[c] : c.normalize('NFD').replace(/[\u0300-\u036f]/g, '')));
}

// Correspondance des champs personnalisés Pipedrive (clés de 40 caractères) et des identifiants,
// lus dans l'environnement : AC_PD_CHAMPS et AC_PD_IDS (voir automation/n8n/parametres.env.example).
const C = JSON.parse($env.AC_PD_CHAMPS || '{}');
const IDS = JSON.parse($env.AC_PD_IDS || '{}');
const champ = (objet, nom) => (C[nom] && objet ? objet[C[nom]] : undefined);
function champs(valeurs) { const o = {}; for (const [k, v] of Object.entries(valeurs)) if (C[k] && v !== undefined) o[C[k]] = v; return o; }
// Service en toutes lettres, avec son article : « vos travaux de peinture ».
const SERVICES = { placo: 'vos travaux de placo', peinture: 'vos travaux de peinture', 'isolation-acoustique': 'votre isolation acoustique',
  'cloisons-isothermes': 'vos cloisons isolantes', plusieurs: 'vos travaux', 'ne-sait-pas': 'vos travaux' };
const serviceTexte = (slug) => SERVICES[slug] || 'vos travaux';
const majuscule = (s) => s.charAt(0).toUpperCase() + s.slice(1);
const urlPipedrive = (id) => 'https://' + ($env.AC_PD_DOMAINE || 'app') + '.pipedrive.com/deal/' + id;

// Même syntaxe que site/api/lib/Modeles.php : {{x}}, {{#x}}…{{/x}}, {{^x}}…{{/x}}.
function rendre(g, v) {
  const re = /\{\{([#^])([a-z0-9_]+)\}\}((?:(?!\{\{[#^]\2\}\})[\s\S])*?)\{\{\/\2\}\}/;
  for (let i = 0; i < 20 && re.test(g); i++) {
    g = g.replace(new RegExp(re.source, 'g'), (m, t, k, c) => ((t === '#') === !!v[k] ? c : ''));
  }
  return g.replace(/\{\{([a-z0-9_]+)\}\}/g, (m, k) => (v[k] === undefined || v[k] === null ? '' : String(v[k])));
}
function message(id, v) {
  const m = MODELES[id];
  return { sujet: rendre(m.sujet, v), texte: rendre(m.corps, v).trim() + '\n' };
}
// Version HTML sobre (paragraphes, liens complets), sans image ni pixel de suivi.
function versHtml(t) {
  const e = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  const lien = (s) => e(s).replace(/https?:\/\/[^\s<]+/g, (u) => '<a href="' + u + '" style="color:#1D1F22">' + u + '</a>');
  return '<div style="max-width:600px;font-family:Arial,sans-serif;font-size:17px;line-height:1.55;color:#1D1F22">'
    + t.trim().split(/\n{2,}/).map((b) => b.startsWith('--\n')
      ? '<hr style="border:0;border-top:1px solid #D9DBDE"><p style="font-size:14px;color:#44494F">' + b.slice(3).split('\n').map(lien).join('<br>') + '</p>'
      : '<p>' + b.split('\n').map(lien).join('<br>') + '</p>').join('') + '</div>';
}
function signature(associe) {
  return [associe, 'Andy Construct · Route des Acacias 48, 1227 Carouge', '+41 22 771 20 15 · www.andyconstruct.ch'].filter(Boolean).join('\n');
}
const MODELES = {
 "sms-nouvelle-demande": {
  "sujet": "",
  "corps": "Andy · Demande {{priorite}} · {{nom_court}}, {{commune}} · {{service}}{{#surface}}, {{surface}}{{/surface}}{{#delai}}, {{delai}}{{/delai}} · Tél. {{telephone}} · Rappeler avant {{echeance_hhmm}} · {{lien_action}}"
 },
 "sms-accuse": {
  "sujet": "",
  "corps": "Andy Construct : votre demande (réf. {{ref}}) est bien arrivée. {{associe_court}} vous rappelle {{promesse}}, depuis le +41 22 771 20 15 ou le +41 78 631 14 34."
 }
};

const d = $input.first().json.demande;
const s = d.scoring || {};
const role = (d.attribution && d.attribution.role) || 'terrain';
const echeance = s.echeance ? DateTime.fromISO(s.echeance).setZone('Europe/Zurich') : null;
const hhmm = echeance ? echeance.toFormat("H 'h' mm").replace(' h 00', ' h') : '';
const nomCourt = [d.contact.civilite === 'madame' ? 'Mme' : d.contact.civilite === 'monsieur' ? 'M.' : '', d.contact.nom].filter(Boolean).join(' ') || 'nom non indiqué';
const lien = lienAction({ a: 'menu', r: d.ref }, 7);
const vars = {
  priorite: s.priorite === 'hors-cible' ? 'hors cible' : s.priorite, nom_court: nomCourt, commune: d.projet.commune || d.projet.npa || 'lieu ?',
  service: d.projet.service_libelle || 'travaux ?', surface: d.projet.surface, delai: d.projet.delai,
  telephone: d.contact.telephone_affiche || 'pas de tél.', echeance_hhmm: hhmm, lien_action: lien,
  ref: d.ref, associe_court: ((d.attribution && d.attribution.associe) || '').split(' ')[0] || 'Un associé', promesse: s.promesse,
};
const mobileAssocie = $env['AC_ASSOCIE_' + role.toUpperCase() + '_MOBILE'] || $env.AC_ASSOCIE_TERRAIN_MOBILE;
const titre = [d.projet.service_libelle || 'Demande', d.projet.commune, d.contact.nom].filter(Boolean).join(' · ') + ' (' + d.ref + ')';
const source = d.source || {};
const corpsAffaire = Object.assign({
  title: titre,
  pipeline_id: IDS.pipeline_demandes, stage_id: IDS.etape_nouvelle,
  user_id: IDS['utilisateur_' + role],
}, champs({
  ref_demande: d.ref, canal: d.canal, source: source.categorie, source_detail: [source.utm_source, source.utm_medium, source.utm_campaign, source.utm_term].filter(Boolean).join(' / ') || source.libelle,
  connu_par: d.projet.connu_par, type_client: d.projet.type_client, service: d.projet.service, surface: d.projet.surface,
  delai: d.projet.delai, commune: d.projet.commune, zone: d.projet.zone, score: s.score, priorite: s.priorite,
  sla_echeance: s.echeance, tentatives_appel: 0, relance_sla_niveau: 0, relance_offre_etape: 0,
}));
const note = [
  '<b>Demande ' + d.ref + '</b> (' + d.formulaire + ', ' + d.canal + ')',
  d.projet.message ? '<p>' + d.projet.message.replace(/</g, '&lt;').replace(/\n/g, '<br>') + '</p>' : '',
  'Score ' + s.score + ' · priorité ' + s.priorite + ' · ' + (s.detail || []).map((l) => l.critere + ' ' + l.valeur + ' (' + l.points + ')').join(', '),
  (s.regles || []).concat(s.hors_cible || []).join(' · '),
  'Source : ' + (source.libelle || '') + (source.page_entree ? ' · entrée ' + source.page_entree : ''),
].filter(Boolean).join('<br>');
const recherche = d.contact.email || d.contact.telephone;
return [{ json: {
  d, recherche, corps_affaire: corpsAffaire, note,
  corps_personne: { name: [d.contact.prenom, d.contact.nom].filter(Boolean).join(' ') || d.contact.telephone_affiche || d.ref,
    email: d.contact.email ? [{ value: d.contact.email, primary: true }] : [], phone: d.contact.telephone ? [{ value: d.contact.telephone, primary: true }] : [] },
  sms_interne: { a: mobileAssocie, texte: versGsm(rendre(MODELES['sms-nouvelle-demande'].corps, vars)) },
  sms_accuse: { a: d.contact.telephone, texte: versGsm(rendre(MODELES['sms-accuse'].corps, vars)) },
  accuse_sms: !d.contact.email && d.contact.telephone_mobile && d.contact.telephone_suisse && d.canal === 'site',
}}];

const prep = $('Préparer la demande').first().json;
const r = $input.first().json;
const items = (r.data && r.data.items) || [];
return [{ json: { ...prep, person_id: items.length ? items[0].item.id : null } }];

const prep = $('Personne trouvée ?').first().json;
const affaires = ($input.first().json.data || []).filter((a) => a && a.add_time);
const limite = Date.now() - 30 * 86400000;
const recente = affaires.find((a) => new Date(a.add_time.replace(' ', 'T') + 'Z').getTime() >= limite);
return [{ json: { ...prep, doublon: !!recente, deal_existant: recente ? recente.id : null } }];

// Jours ouvrables (lu-ve) hors jours fériés genevois et fermetures (AC_JOURS_FERMES = "2027-07-19,2027-07-20").
function paques(a) {
  const b = Math.floor(a / 100), c = a % 100, d = Math.floor(b / 4), e = b % 4, f = Math.floor((b + 8) / 25),
    g = Math.floor((b - f + 1) / 3), h = (19 * (a % 19) + b - d - g + 15) % 30, i = Math.floor(c / 4), k = c % 4,
    l = (32 + 2 * e + 2 * i - h - k) % 7, m = Math.floor(((a % 19) + 11 * h + 22 * l) / 451);
  return DateTime.fromObject({ year: a, month: Math.floor((h + l - 7 * m + 114) / 31), day: ((h + l - 7 * m + 114) % 31) + 1 }, { zone: 'Europe/Zurich' });
}
function feries(a) {
  const p = paques(a), j = (n) => p.plus({ days: n }).toISODate();
  const jeune = DateTime.fromObject({ year: a, month: 9, day: 1 }, { zone: 'Europe/Zurich' });
  const premierDimanche = jeune.plus({ days: (7 - jeune.weekday) % 7 });
  return [a + '-01-01', j(-2), j(1), j(39), j(50), a + '-08-01', premierDimanche.plus({ days: 4 }).toISODate(), a + '-12-25', a + '-12-31']
    .concat(String($env.AC_JOURS_FERMES || '').split(',').map((s) => s.trim()).filter(Boolean));
}
const estOuvrable = (dt) => dt.weekday <= 5 && !feries(dt.year).includes(dt.toISODate());
const maintenant = () => DateTime.now().setZone('Europe/Zurich');

const j = $input.first().json;
let t = maintenant();
const prioriteA = j.d.scoring.priorite === 'A';
// Entre 20 h et 7 h : attendre 7 h ; samedi : seulement les A ; dimanche et jours fériés : jour ouvrable suivant.
const ok = (x) => (x.weekday <= 5 && estOuvrable(x)) || (x.weekday === 6 && prioriteA);
let envoi = t;
if (t.hour >= 20 || t.hour < 7 || !ok(t)) {
  envoi = (t.hour >= 20 ? t.plus({ days: 1 }) : t).set({ hour: 7, minute: 0, second: 0 });
  for (let i = 0; i < 7 && !ok(envoi); i++) envoi = envoi.plus({ days: 1 }).set({ hour: 7, minute: 0 });
}
return [{ json: { ...j, attendre: envoi > t.plus({ minutes: 1 }), envoi: envoi.toISO(), sms: j.sms_interne } }];

// Jours ouvrables (lu-ve) hors jours fériés genevois et fermetures (AC_JOURS_FERMES = "2027-07-19,2027-07-20").
function paques(a) {
  const b = Math.floor(a / 100), c = a % 100, d = Math.floor(b / 4), e = b % 4, f = Math.floor((b + 8) / 25),
    g = Math.floor((b - f + 1) / 3), h = (19 * (a % 19) + b - d - g + 15) % 30, i = Math.floor(c / 4), k = c % 4,
    l = (32 + 2 * e + 2 * i - h - k) % 7, m = Math.floor(((a % 19) + 11 * h + 22 * l) / 451);
  return DateTime.fromObject({ year: a, month: Math.floor((h + l - 7 * m + 114) / 31), day: ((h + l - 7 * m + 114) % 31) + 1 }, { zone: 'Europe/Zurich' });
}
function feries(a) {
  const p = paques(a), j = (n) => p.plus({ days: n }).toISODate();
  const jeune = DateTime.fromObject({ year: a, month: 9, day: 1 }, { zone: 'Europe/Zurich' });
  const premierDimanche = jeune.plus({ days: (7 - jeune.weekday) % 7 });
  return [a + '-01-01', j(-2), j(1), j(39), j(50), a + '-08-01', premierDimanche.plus({ days: 4 }).toISODate(), a + '-12-25', a + '-12-31']
    .concat(String($env.AC_JOURS_FERMES || '').split(',').map((s) => s.trim()).filter(Boolean));
}
const estOuvrable = (dt) => dt.weekday <= 5 && !feries(dt.year).includes(dt.toISODate());
const maintenant = () => DateTime.now().setZone('Europe/Zurich');

const j = $input.first().json;
const t = maintenant();
// Prospects : en semaine 8 h - 19 h 30, samedi 9 h - 12 h, jamais le dimanche ni un jour férié.
const dansLaPlage = (x) => (x.weekday <= 5 && estOuvrable(x) && x.hour >= 8 && (x.hour < 19 || (x.hour === 19 && x.minute < 30)))
  || (x.weekday === 6 && x.hour >= 9 && x.hour < 12);
let envoi = t;
for (let i = 0; i < 400 && !dansLaPlage(envoi); i++) envoi = envoi.plus({ minutes: 30 }).set({ second: 0 });
return [{ json: { ...j, attendre: envoi > t.plus({ minutes: 1 }), envoi: envoi.toISO(), sms: j.sms_accuse } }];
